package com.puzzlehunt;

/** Shared formatting helpers for hunt timer / split displays. */
final class TimeFormat
{
	private TimeFormat() {}

	/** Formats a millisecond duration as {@code mm:ss.t} (tenths of a second). */
	static String formatTime(long ms)
	{
		long totalSec = ms / 1000L;
		long mins = totalSec / 60L;
		long secs = totalSec % 60L;
		long tenths = (ms % 1000L) / 100L;
		return String.format("%02d:%02d.%d", mins, secs, tenths);
	}
}

package com.puzzlehunt;

import java.awt.Color;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.AbstractButton;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Shared helpers for sidebar styling. Mirrors the look-and-feel used by
 * Quest Helper / RuneLite-bundled plugins (dark backgrounds, no L&amp;F
 * decoration painting, hover highlight) instead of relying on the
 * platform default which renders a light "system" button.
 */
final class PanelComponents
{
	private PanelComponents() {}

	/** Apply RuneLite-style dark theming to a button. */
	static <T extends AbstractButton> T styleButton(T button)
	{
		button.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		button.setForeground(Color.WHITE);
		button.setFocusPainted(false);
		button.setBorderPainted(false);
		button.setOpaque(true);
		button.setBorder(BorderFactory.createEmptyBorder(4, 8, 4, 8));
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.addMouseListener(new MouseAdapter()
		{
			private final Color base = button.getBackground();
			private final Color hover = ColorScheme.DARKER_GRAY_HOVER_COLOR;

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (button.isEnabled())
				{
					button.setBackground(hover);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				button.setBackground(base);
			}
		});
		return button;
	}

	/** Convenience for {@code styleButton(new JButton(text))}. */
	static JButton button(String text)
	{
		return styleButton(new JButton(text));
	}

	/**
	 * A panel whose preferred width tracks its parent (typically a
	 * {@link javax.swing.JScrollPane} viewport), so children that report
	 * unbounded preferred widths still wrap inside the sidebar instead of
	 * triggering a horizontal scrollbar.
	 */
	static class FixedWidthPanel extends JPanel
	{
		@Override
		public Dimension getPreferredSize()
		{
			Container parent = getParent();
			int width = parent != null ? parent.getWidth() : PluginPanel.PANEL_WIDTH;
			if (width <= 0)
			{
				width = PluginPanel.PANEL_WIDTH;
			}
			return new Dimension(width, super.getPreferredSize().height);
		}

		@Override
		public Dimension getMaximumSize()
		{
			return getPreferredSize();
		}
	}
}

package com.puzzlehunt;

import com.puzzlehunt.model.SerializedTile;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Geometry helpers for the "walk loop" tile capture flow:
 *
 * <ol>
 *   <li>The player presses <em>Walk loop</em> and walks along the boundary
 *   of the area they want to mark.</li>
 *   <li>Each game tick samples the player's tile.</li>
 *   <li>On <em>Finish loop</em> the samples are reduced to a convex hull
 *   and every integer tile inside (or on) the hull is added to the
 *   step's tile list.</li>
 * </ol>
 *
 * <p>Convex hull is computed with Andrew's monotone chain in O(n log n).
 * Interior tiles are enumerated by ray-casting each integer tile centre
 * against the hull polygon. All work is done on plain ints so it stays
 * out of the client thread.
 */
final class TileHull
{
	private TileHull() {}

	/**
	 * Returns the set of tiles forming the filled convex hull of the
	 * supplied samples (all on the same plane). Returns an empty list if
	 * fewer than one sample is supplied.
	 */
	static List<SerializedTile> hullFill(List<SerializedTile> samples)
	{
		if (samples == null || samples.isEmpty())
		{
			return new ArrayList<>();
		}
		int plane = samples.get(0).getPlane();
		// Dedupe samples on this plane.
		Set<Long> seen = new HashSet<>();
		List<int[]> pts = new ArrayList<>(samples.size());
		for (SerializedTile t : samples)
		{
			if (t.getPlane() != plane)
			{
				continue;
			}
			long k = (((long) t.getX()) << 32) | (t.getY() & 0xffffffffL);
			if (seen.add(k))
			{
				pts.add(new int[]{t.getX(), t.getY()});
			}
		}
		if (pts.isEmpty())
		{
			return new ArrayList<>();
		}
		if (pts.size() == 1)
		{
			List<SerializedTile> single = new ArrayList<>(1);
			single.add(new SerializedTile(pts.get(0)[0], pts.get(0)[1], plane));
			return single;
		}

		List<int[]> hull = convexHull(pts);
		// Bounding box.
		int minX = Integer.MAX_VALUE, maxX = Integer.MIN_VALUE;
		int minY = Integer.MAX_VALUE, maxY = Integer.MIN_VALUE;
		for (int[] p : hull)
		{
			if (p[0] < minX) minX = p[0];
			if (p[0] > maxX) maxX = p[0];
			if (p[1] < minY) minY = p[1];
			if (p[1] > maxY) maxY = p[1];
		}
		List<SerializedTile> out = new ArrayList<>();
		for (int x = minX; x <= maxX; x++)
		{
			for (int y = minY; y <= maxY; y++)
			{
				if (insideOrOnPolygon(hull, x, y))
				{
					out.add(new SerializedTile(x, y, plane));
				}
			}
		}
		return out;
	}

	private static List<int[]> convexHull(List<int[]> input)
	{
		List<int[]> pts = new ArrayList<>(input);
		pts.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
		int n = pts.size();
		int[][] hull = new int[2 * n][];
		int k = 0;
		// Lower hull
		for (int[] p : pts)
		{
			while (k >= 2 && cross(hull[k - 2], hull[k - 1], p) <= 0) k--;
			hull[k++] = p;
		}
		// Upper hull
		int lower = k + 1;
		for (int i = n - 2; i >= 0; i--)
		{
			int[] p = pts.get(i);
			while (k >= lower && cross(hull[k - 2], hull[k - 1], p) <= 0) k--;
			hull[k++] = p;
		}
		List<int[]> out = new ArrayList<>(k - 1);
		for (int i = 0; i < k - 1; i++)
		{
			out.add(hull[i]);
		}
		return out;
	}

	private static long cross(int[] o, int[] a, int[] b)
	{
		return (long) (a[0] - o[0]) * (b[1] - o[1]) - (long) (a[1] - o[1]) * (b[0] - o[0]);
	}

	/**
	 * Test whether the integer tile (x,y) lies inside or on the convex
	 * polygon. Uses the half-plane test which is exact for convex
	 * polygons and avoids the ambiguity of ray casting on edges.
	 */
	private static boolean insideOrOnPolygon(List<int[]> hull, int x, int y)
	{
		int n = hull.size();
		if (n == 0) return false;
		if (n == 1) return hull.get(0)[0] == x && hull.get(0)[1] == y;
		// All cross products should have the same sign (or zero) for
		// the point to be inside a CCW polygon.
		boolean hasPos = false, hasNeg = false;
		for (int i = 0; i < n; i++)
		{
			int[] a = hull.get(i);
			int[] b = hull.get((i + 1) % n);
			long c = (long) (b[0] - a[0]) * (y - a[1]) - (long) (b[1] - a[1]) * (x - a[0]);
			if (c > 0) hasPos = true;
			else if (c < 0) hasNeg = true;
			if (hasPos && hasNeg) return false;
		}
		return true;
	}
}

package com.puzzlehunt;

import com.puzzlehunt.model.PuzzleStep;
import com.puzzlehunt.model.SerializedTile;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Renders, while a step is being edited:
 * <ul>
 *   <li>Each tile already saved on the step at low opacity ("valid
 *       trigger" tiles).</li>
 *   <li>Each tile sampled by the in-progress walk-loop, in a different
 *       hue, so the user gets live feedback.</li>
 * </ul>
 *
 * <p>To stay within the "no per-frame scene scans" guideline, the
 * overlay only iterates the configured tile lists (typically &lt; 200
 * tiles) and relies on RuneLite's culling at render time.
 */
@Singleton
public class TileSelectionOverlay extends Overlay
{
	private static final Color VALID_FILL = new Color(0, 200, 255, 40);
	private static final Color VALID_BORDER = new Color(0, 200, 255, 120);
	private static final Color SAMPLE_FILL = new Color(255, 200, 0, 80);
	private static final Color SAMPLE_BORDER = new Color(255, 200, 0, 220);
	private static final Color START_FILL = new Color(60, 220, 90, 80);
	private static final Color START_BORDER = new Color(60, 220, 90, 220);
	private static final Stroke STROKE = new BasicStroke(1.5f);

	private final Client client;
	private final CompletionDetector detector;

	/** Step being edited; null disables rendering. */
	@Setter
	private volatile PuzzleStep editStep;

	/** Starting tile for the hunt currently shown on the detail page; null hides it. */
	@Setter
	private volatile SerializedTile startingTile;

	@Inject
	TileSelectionOverlay(Client client, CompletionDetector detector)
	{
		this.client = client;
		this.detector = detector;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_MED);
	}

	@Override
	public java.awt.Dimension render(Graphics2D g)
	{
		PuzzleStep step = editStep;
		SerializedTile start = startingTile;
		if (step == null && start == null)
		{
			return null;
		}
		Player local = client.getLocalPlayer();
		WorldView wv = client.getTopLevelWorldView();
		Scene scene = wv == null ? null : wv.getScene();
		if (local == null || scene == null)
		{
			return null;
		}
		WorldPoint here = local.getWorldLocation();
		if (here == null)
		{
			return null;
		}
		int plane = wv.getPlane();
		g.setStroke(STROKE);

		if (start != null)
		{
			drawTiles(g, here, plane, java.util.Collections.singletonList(start), START_FILL, START_BORDER);
		}

		if (step != null)
		{
			// Saved valid-trigger tiles.
			List<SerializedTile> tiles = step.getTiles();
			if (tiles != null)
			{
				drawTiles(g, here, plane, tiles, VALID_FILL, VALID_BORDER);
			}

			// Live walk-loop samples (only for the step currently being captured).
			if (detector.getSampleStep() == step)
			{
				List<SerializedTile> samples = detector.getSampleBuffer();
				drawTiles(g, here, plane, samples, SAMPLE_FILL, SAMPLE_BORDER);
			}
		}
		return null;
	}

	private void drawTiles(Graphics2D g, WorldPoint here, int plane,
		List<SerializedTile> tiles, Color fill, Color border)
	{
		for (SerializedTile t : tiles)
		{
			if (t.getPlane() != plane)
			{
				continue;
			}
			WorldPoint wp = new WorldPoint(t.getX(), t.getY(), t.getPlane());
			if (wp.distanceTo(here) > Perspective.SCENE_SIZE)
			{
				continue;
			}
			LocalPoint lp = LocalPoint.fromWorld(client, wp);
			if (lp == null)
			{
				continue;
			}
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}
			g.setColor(fill);
			g.fillPolygon(poly);
			g.setColor(border);
			g.drawPolygon(poly);
		}
	}
}

package com.puzzlehunt;

import com.puzzlehunt.model.HuntMode;
import com.puzzlehunt.model.HuntProgress;
import com.puzzlehunt.model.PuzzleHunt;
import com.puzzlehunt.model.PuzzleStep;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Owns the currently-running puzzle hunt: timer accumulation, completion
 * tracking, persistence and end-of-hunt detection.
 *
 * <p>The timer is split into a persisted {@link HuntProgress#getElapsedMillis()
 * elapsedMillis} accumulator plus a transient {@link
 * HuntProgress#getSessionStartMillis() sessionStartMillis} marker. Calling
 * {@link #pauseTimer()} folds the live session into the accumulator, so
 * shutting RuneLite down at any point loses at most the time since the last
 * state-write tick.
 */
@Slf4j
@Singleton
public class ActiveHuntService
{
	/** Listener for any state change that the UI should re-render on. */
	public interface Listener
	{
		void onActiveHuntChanged();
	}

	private final HuntManager huntManager;
	private final List<Listener> listeners = new CopyOnWriteArrayList<>();

	@Getter
	private PuzzleHunt activeHunt;

	@Getter
	private HuntProgress activeProgress;

	@Inject
	ActiveHuntService(HuntManager huntManager)
	{
		this.huntManager = huntManager;
	}

	public void addListener(Listener l)
	{
		listeners.add(l);
	}

	public void removeListener(Listener l)
	{
		listeners.remove(l);
	}

	private void fireChanged()
	{
		for (Listener l : listeners)
		{
			try
			{
				l.onActiveHuntChanged();
			}
			catch (RuntimeException e)
			{
				log.debug("Listener threw", e);
			}
		}
	}

	/** Begins a hunt immediately. Loads (or initialises) progress for it. */
	public synchronized void start(PuzzleHunt hunt)
	{
		if (hunt == null)
		{
			return;
		}
		// Persist any in-flight hunt before swapping.
		if (activeHunt != null && activeProgress != null)
		{
			pauseTimer();
			persistQuietly();
		}
		this.activeHunt = hunt;
		this.activeProgress = huntManager.loadProgress(hunt.getId());
		if (activeProgress.isCompleted())
		{
			// Re-running a completed hunt — leave the splits intact for display
			// but don't restart the timer until the user resets.
			fireChanged();
			return;
		}
		startTimer();
		fireChanged();
	}

	/** Stops tracking the current hunt without clearing it from disk. */
	public synchronized void stop()
	{
		if (activeHunt == null)
		{
			return;
		}
		pauseTimer();
		persistQuietly();
		this.activeHunt = null;
		this.activeProgress = null;
		fireChanged();
	}

	/** Resumes the timer for the active hunt. No-op if there is no active hunt. */
	public synchronized void startTimer()
	{
		if (activeProgress == null || activeProgress.isCompleted())
		{
			return;
		}
		if (activeProgress.getSessionStartMillis() == 0L)
		{
			activeProgress.setSessionStartMillis(System.currentTimeMillis());
			persistQuietly();
			fireChanged();
		}
	}

	/** Folds the running session into the persisted accumulator. */
	public synchronized void pauseTimer()
	{
		if (activeProgress == null)
		{
			return;
		}
		long start = activeProgress.getSessionStartMillis();
		if (start != 0L)
		{
			long delta = Math.max(0L, System.currentTimeMillis() - start);
			activeProgress.setElapsedMillis(activeProgress.getElapsedMillis() + delta);
			activeProgress.setSessionStartMillis(0L);
			persistQuietly();
			fireChanged();
		}
	}

	/** True iff there is an active hunt with the timer currently running. */
	public synchronized boolean isTimerRunning()
	{
		return activeProgress != null && activeProgress.getSessionStartMillis() != 0L;
	}

	/** Total elapsed milliseconds for the active hunt, including any live session. */
	public synchronized long getElapsedMillis()
	{
		if (activeProgress == null)
		{
			return 0L;
		}
		long base = activeProgress.getElapsedMillis();
		long start = activeProgress.getSessionStartMillis();
		if (start != 0L)
		{
			base += Math.max(0L, System.currentTimeMillis() - start);
		}
		return base;
	}

	/**
	 * In treasure-trail mode, the index of the step currently being attempted.
	 * In diary mode this is meaningless; callers should use
	 * {@link #getCompletedStepIds()} instead.
	 */
	public synchronized int getCurrentStepIndex()
	{
		return activeProgress == null ? 0 : activeProgress.getCurrentStepIndex();
	}

	/** Completed step ids. */
	public synchronized Set<String> getCompletedStepIds()
	{
		if (activeProgress == null)
		{
			return Collections.emptySet();
		}
		return new java.util.LinkedHashSet<>(activeProgress.getStepSplits().keySet());
	}

	/**
	 * Marks the given step complete. In treasure-trail mode only the current
	 * step can be completed; out-of-order completions are ignored. In diary
	 * mode any uncompleted step can be completed.
	 *
	 * @return true if the call advanced state (the step was newly completed)
	 */
	public synchronized boolean completeStep(String stepId)
	{
		if (activeHunt == null || activeProgress == null || activeProgress.isCompleted())
		{
			return false;
		}
		List<PuzzleStep> steps = activeHunt.getSteps();
		if (steps == null || steps.isEmpty())
		{
			return false;
		}
		if (activeProgress.getStepSplits().containsKey(stepId))
		{
			return false;
		}

		if (activeHunt.getMode() == HuntMode.TREASURE_TRAIL)
		{
			// Step must be among the chapter-aware active set: it has to be in
			// the current chapter, and (for sequential chapters) the first
			// uncompleted step within it.
			boolean allowed = false;
			for (PuzzleStep s : computeActiveSteps())
			{
				if (s.getId().equals(stepId))
				{
					allowed = true;
					break;
				}
			}
			if (!allowed)
			{
				return false;
			}
			recordSplit(stepId);
			// Maintain currentStepIndex as a hint to the first uncompleted step
			// in source order, used by the UI for "future" masking fallbacks.
			activeProgress.setCurrentStepIndex(firstUncompletedIndex(steps));
		}
		else
		{
			// DIARY: just check the id exists in the hunt.
			boolean found = false;
			for (PuzzleStep s : steps)
			{
				if (s.getId().equals(stepId))
				{
					found = true;
					break;
				}
			}
			if (!found)
			{
				return false;
			}
			recordSplit(stepId);
		}

		// End of hunt?
		if (activeProgress.getStepSplits().size() >= steps.size())
		{
			activeProgress.setCompleted(true);
			pauseTimer();
		}

		persistQuietly();
		fireChanged();
		return true;
	}

	/**
	 * Returns the {@link PuzzleStep} the player should currently focus on
	 * (treasure-trail mode), or {@code null} for diary mode / no active hunt.
	 */
	public synchronized PuzzleStep getCurrentStep()
	{
		if (activeHunt == null || activeProgress == null)
		{
			return null;
		}
		if (activeHunt.getMode() != HuntMode.TREASURE_TRAIL)
		{
			return null;
		}
		List<PuzzleStep> active = computeActiveSteps();
		return active.isEmpty() ? null : active.get(0);
	}

	/**
	 * Lowest chapter index that still has uncompleted steps in a TREASURE_TRAIL
	 * hunt. Returns -1 when there is no active hunt or every step is complete.
	 * Always -1 in DIARY hunts (chapters are not used).
	 */
	public synchronized int getActiveChapter()
	{
		if (activeHunt == null || activeProgress == null || activeProgress.isCompleted())
		{
			return -1;
		}
		if (activeHunt.getMode() != HuntMode.TREASURE_TRAIL)
		{
			return -1;
		}
		java.util.Set<String> done = activeProgress.getStepSplits().keySet();
		int min = Integer.MAX_VALUE;
		for (PuzzleStep s : activeHunt.getSteps())
		{
			if (done.contains(s.getId())) continue;
			if (s.getChapter() < min) min = s.getChapter();
		}
		return min == Integer.MAX_VALUE ? -1 : min;
	}

	/**
	 * True when the given step belongs to a chapter strictly after the active
	 * one (and so should be hidden from the player in TREASURE_TRAIL mode).
	 */
	public synchronized boolean isStepHidden(PuzzleStep step)
	{
		if (step == null || activeHunt == null) return false;
		if (activeHunt.getMode() != HuntMode.TREASURE_TRAIL) return false;
		int active = getActiveChapter();
		if (active < 0) return false;
		return step.getChapter() > active;
	}

	private List<PuzzleStep> computeActiveSteps()
	{
		List<PuzzleStep> steps = activeHunt.getSteps();
		if (steps == null || steps.isEmpty()) return Collections.emptyList();
		java.util.Set<String> done = activeProgress.getStepSplits().keySet();
		int chapter = getActiveChapter();
		if (chapter < 0) return Collections.emptyList();
		HuntMode chapterMode = activeHunt.getChapterMode(chapter);
		List<PuzzleStep> chapterSteps = new ArrayList<>();
		for (PuzzleStep s : steps)
		{
			if (s.getChapter() == chapter && !done.contains(s.getId()))
			{
				chapterSteps.add(s);
			}
		}
		if (chapterSteps.isEmpty()) return Collections.emptyList();
		if (chapterMode == HuntMode.DIARY) return chapterSteps;
		// Sequential within chapter: only the first uncompleted step is active.
		return Collections.singletonList(chapterSteps.get(0));
	}

	private int firstUncompletedIndex(List<PuzzleStep> steps)
	{
		java.util.Set<String> done = activeProgress.getStepSplits().keySet();
		for (int i = 0; i < steps.size(); i++)
		{
			if (!done.contains(steps.get(i).getId())) return i;
		}
		return steps.size();
	}

	/**
	 * Steps the detector should currently watch for completion of. In
	 * treasure-trail mode that's only the current step; in diary mode it's
	 * every uncompleted step.
	 */
	public synchronized List<PuzzleStep> getActiveStepsForDetection()
	{
		if (activeHunt == null || activeProgress == null || activeProgress.isCompleted())
		{
			return Collections.emptyList();
		}
		List<PuzzleStep> steps = activeHunt.getSteps();
		if (activeHunt.getMode() == HuntMode.TREASURE_TRAIL)
		{
			return computeActiveSteps();
		}
		List<PuzzleStep> out = new ArrayList<>();
		for (PuzzleStep s : steps)
		{
			if (!activeProgress.getStepSplits().containsKey(s.getId()))
			{
				out.add(s);
			}
		}
		return out;
	}

	/** Wipes progress so the active (or named) hunt can be replayed from scratch. */
	public synchronized void reset(String huntId)
	{
		if (huntId == null)
		{
			return;
		}
		HuntProgress fresh = new HuntProgress();
		fresh.setHuntId(huntId);
		try
		{
			huntManager.saveProgress(fresh);
		}
		catch (IOException e)
		{
			log.debug("Failed to reset progress for {}", huntId, e);
		}
		if (activeHunt != null && huntId.equals(activeHunt.getId()))
		{
			this.activeProgress = fresh;
			startTimer();
			fireChanged();
		}
	}

	private void recordSplit(String stepId)
	{
		long now = getElapsedMillis();
		activeProgress.getStepSplits().put(stepId, now);
	}

	private void persistQuietly()
	{
		try
		{
			huntManager.saveProgress(activeProgress);
		}
		catch (IOException e)
		{
			log.debug("Failed to persist progress for hunt {}", activeProgress.getHuntId(), e);
		}
	}
}

