/**
 * Detail view for a single saved hunt — Start now, Sync start (with countdown
 * to the next whole minute, ≥60s), Edit and Delete.
 */
@Slf4j
class HuntDetailView extends JPanel
{
	/** Sound played for each of the 3, 2, 1 ticks (iron_door_open). */
	private static final int SOUND_TICK = 71;
	/** Sound played at GO! (quick_teleport). */
	private static final int SOUND_GO = 198;
	private final PuzzleHuntPanel host;
	private final JLabel title = new JLabel();
	private final JLabel meta = new JLabel();
	private final JLabel progressLabel = new JLabel();
	private final JLabel countdown = new JLabel(" ");
	private final JPanel briefingPanel = new JPanel();

	/** Snapshot of inventory item counts populated on the client thread. UI reads this. */
	private volatile Map<Integer, Integer> inventorySnapshot = java.util.Collections.emptyMap();
	private final JButton startNow = PanelComponents.styleButton(new JButton("Start now"));
	private final JButton syncStart = PanelComponents.styleButton(new JButton("Sync start"));
	private final JButton cancelSync = PanelComponents.styleButton(new JButton("Cancel countdown"));
	private final JButton edit = PanelComponents.styleButton(new JButton("Edit"));
	private final JButton resetBtn = PanelComponents.styleButton(new JButton("Reset progress"));
	private final JButton exportBtn = PanelComponents.styleButton(new JButton("Export (copy code)"));
	private final JButton delete = PanelComponents.styleButton(new JButton("Delete"));
	private final JButton back = PanelComponents.styleButton(new JButton("← Back"));

	private PuzzleHunt hunt;
	private long countdownTargetMs;
	/** Used so we only play each countdown sound once per second. */
	private int lastCountdownDigit = -1;

	HuntDetailView(PuzzleHuntPanel host)
	{
		this.host = host;
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		back.setAlignmentX(Component.LEFT_ALIGNMENT);
		back.addActionListener(e ->
		{
			cancelCountdownIfRunning();
			host.showHome();
		});
		header.add(back);
		header.add(Box.createVerticalStrut(6));
		title.setForeground(Color.WHITE);
		title.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(title);
		meta.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		meta.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(meta);
		progressLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		progressLabel.setAlignmentX(Component.LEFT_ALIGNMENT);
		header.add(progressLabel);
		add(header, BorderLayout.NORTH);

		JPanel buttons = new JPanel();
		buttons.setLayout(new BoxLayout(buttons, BoxLayout.Y_AXIS));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);

		briefingPanel.setLayout(new BoxLayout(briefingPanel, BoxLayout.Y_AXIS));
		briefingPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		briefingPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		buttons.add(briefingPanel);
		buttons.add(Box.createVerticalStrut(8));

		startNow.addActionListener(e -> onStartNow());
		addStacked(buttons, startNow);
		syncStart.addActionListener(e -> onSyncStart());
		addStacked(buttons, syncStart);
		countdown.setForeground(Color.WHITE);
		countdown.setAlignmentX(Component.LEFT_ALIGNMENT);
		buttons.add(countdown);
		cancelSync.addActionListener(e -> cancelCountdownIfRunning());
		cancelSync.setVisible(false);
		addStacked(buttons, cancelSync);
		edit.addActionListener(e -> host.showCreate(hunt));
		addStacked(buttons, edit);
		resetBtn.addActionListener(e -> onReset());
		addStacked(buttons, resetBtn);
		exportBtn.addActionListener(e -> onExport());
		addStacked(buttons, exportBtn);
		delete.addActionListener(e -> onDelete());
		addStacked(buttons, delete);
		add(buttons, BorderLayout.CENTER);
	}

	/**
	 * Add a button to a {@link BoxLayout} column without letting it
	 * stretch to fill leftover vertical space (the GridLayout default
	 * made every button render as a tall square).
	 */
	private static void addStacked(JPanel parent, JButton b)
	{
		b.setAlignmentX(Component.LEFT_ALIGNMENT);
		Dimension pref = b.getPreferredSize();
		b.setMaximumSize(new Dimension(Integer.MAX_VALUE, pref.height));
		parent.add(b);
		parent.add(Box.createVerticalStrut(4));
	}

	void setHunt(PuzzleHunt hunt)
	{
		this.hunt = hunt;
		cancelCountdownIfRunning();
		refresh();
		refreshInventorySnapshot();
	}

	private void refresh()
	{
		if (hunt == null)
		{
			title.setText("(no hunt)");
			meta.setText("");
			progressLabel.setText("");
			briefingPanel.removeAll();
			briefingPanel.revalidate();
			briefingPanel.repaint();
			return;
		}
		title.setText(hunt.getName());
		String modeLabel = hunt.getMode() == HuntMode.TREASURE_TRAIL ? "Treasure Trail" : "Diary";
		int total = hunt.getSteps() == null ? 0 : hunt.getSteps().size();
		meta.setText(modeLabel + " — " + total + " step" + (total == 1 ? "" : "s"));
		HuntProgress p = host.getHuntManager().loadProgress(hunt.getId());
		int done = p.getStepSplits() == null ? 0 : p.getStepSplits().size();
		progressLabel.setText("Progress: " + done + "/" + total + (p.isCompleted() ? " — completed" : ""));
		resetBtn.setVisible(done > 0 || p.isCompleted());
		rebuildBriefing();
	}

	private void rebuildBriefing()
	{
		briefingPanel.removeAll();
		if (hunt == null)
		{
			briefingPanel.revalidate();
			briefingPanel.repaint();
			return;
		}
		String instructions = hunt.getStartingInstructions();
		SerializedTile tile = hunt.getStartingTile();
		List<Integer> ids = hunt.getStartingItemIds();
		boolean hasInstructions = instructions != null && !instructions.trim().isEmpty();
		boolean hasTile = tile != null;
		boolean hasItems = ids != null && !ids.isEmpty();
		if (!hasInstructions && !hasTile && !hasItems)
		{
			briefingPanel.revalidate();
			briefingPanel.repaint();
			return;
		}

		JLabel header = new JLabel("Briefing");
		header.setForeground(Color.WHITE);
		header.setAlignmentX(Component.LEFT_ALIGNMENT);
		briefingPanel.add(header);

		if (hasInstructions)
		{
			JTextArea ta = new JTextArea(instructions);
			ta.setLineWrap(true);
			ta.setWrapStyleWord(true);
			ta.setEditable(false);
			ta.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			ta.setForeground(Color.WHITE);
			ta.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
			ta.setAlignmentX(Component.LEFT_ALIGNMENT);
			ta.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
			briefingPanel.add(ta);
		}

		if (hasTile)
		{
			JLabel tl = new JLabel("Start at: " + tile.getX() + ", " + tile.getY()
				+ " (plane " + tile.getPlane() + ")");
			tl.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			tl.setAlignmentX(Component.LEFT_ALIGNMENT);
			briefingPanel.add(tl);
		}

		if (hasItems)
		{
			JLabel itemsHdr = new JLabel("Required items:");
			itemsHdr.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			itemsHdr.setAlignmentX(Component.LEFT_ALIGNMENT);
			briefingPanel.add(itemsHdr);
			List<String> names = hunt.getStartingItemNames();
			Map<Integer, Integer> inv = inventorySnapshot;
			for (int i = 0; i < ids.size(); i++)
			{
				int id = ids.get(i);
				String display = names != null && i < names.size() && names.get(i) != null
					? names.get(i) : ("#" + id);
				boolean present = inv.getOrDefault(id, 0) > 0;
				JPanel row = new JPanel(new BorderLayout(4, 0));
				row.setBackground(present ? PRESENT_BG : MISSING_BG);
				row.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
				row.setAlignmentX(Component.LEFT_ALIGNMENT);
				row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
				JLabel icon = new JLabel();
				icon.setPreferredSize(new Dimension(32, 24));
				loadItemIcon(icon, id);
				row.add(icon, BorderLayout.WEST);
				JLabel nm = new JLabel(display);
				nm.setForeground(Color.WHITE);
				row.add(nm, BorderLayout.CENTER);
				JLabel status = new JLabel(present ? "✓" : "✗");
				status.setForeground(Color.WHITE);
				row.add(status, BorderLayout.EAST);
				briefingPanel.add(row);
				briefingPanel.add(Box.createVerticalStrut(2));
			}
		}

		briefingPanel.revalidate();
		briefingPanel.repaint();
	}

	/** Quest-helper-style highlight colours for the required-items list. */
	private static final Color PRESENT_BG = new Color(40, 90, 40);
	private static final Color MISSING_BG = new Color(110, 40, 40);

	private Map<Integer, Integer> readInventoryCounts()
	{
		// Must be called on the client thread — ItemContainer access asserts that.
		Map<Integer, Integer> out = new HashMap<>();
		try
		{
			ItemContainer inv = host.getClient().getItemContainer(InventoryID.INV);
			if (inv == null) return out;
			for (Item item : inv.getItems())
			{
				if (item == null || item.getId() <= 0) continue;
				out.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		catch (Exception ignored)
		{
			// Pre-login the container is null; just show everything as missing.
		}
		return out;
	}

	/** Refreshes {@link #inventorySnapshot} on the client thread, then re-renders the briefing on the EDT. */
	private void refreshInventorySnapshot()
	{
		host.getClientThread().invoke(() ->
		{
			Map<Integer, Integer> snap = readInventoryCounts();
			if (snap.equals(inventorySnapshot))
			{
				return;
			}
			inventorySnapshot = snap;
			SwingUtilities.invokeLater(this::rebuildBriefing);
		});
	}

	private void loadItemIcon(JLabel target, int itemId)
	{
		target.setIcon(null);
		if (itemId <= 0) return;
		host.getClientThread().invoke(() ->
		{
			AsyncBufferedImage img = host.getItemManager().getImage(itemId);
			if (img != null)
			{
				img.addTo(target);
				SwingUtilities.invokeLater(() -> target.setIcon(new ImageIcon(img)));
			}
		});
	}

	void tick()
	{
		// Inventory contents may change while the user lingers on this view, so
		// refresh the briefing's red/green item highlights once per UI tick.
		refreshInventorySnapshot();
		if (countdownTargetMs == 0L)
		{
			return;
		}
		long remaining = countdownTargetMs - System.currentTimeMillis();
		if (remaining <= 0L)
		{
			countdown.setText("Started!");
			countdownTargetMs = 0L;
			cancelSync.setVisible(false);
			syncStart.setEnabled(true);
			startNow.setEnabled(true);
			host.getCountdownOverlay().setText("GO!", new Color(120, 220, 120));
			playSound(SOUND_GO);
			host.getExecutor().schedule(
				() -> host.getCountdownOverlay().clear(),
				1200, java.util.concurrent.TimeUnit.MILLISECONDS);
			host.getActive().start(hunt);
			host.getDetector().resetForNewHunt();
			host.showActive();
			lastCountdownDigit = -1;
		}
		else
		{
			long sec = (remaining + 999L) / 1000L;
			countdown.setText("Sync starting in " + sec + "s…");
			if (sec >= 1 && sec <= 3 && sec != lastCountdownDigit)
			{
				lastCountdownDigit = (int) sec;
				host.getCountdownOverlay().setText(Long.toString(sec), Color.WHITE);
				playSound(SOUND_TICK);
			}
		}
	}

	private void playSound(int soundId)
	{
		// playSoundEffect respects the user's in-game sound effect volume.
		host.getClientThread().invoke(() -> host.getClient().playSoundEffect(soundId));
	}

	private void onStartNow()
	{
		if (hunt == null)
		{
			return;
		}
		// 3 ticks + GO. Use 3500ms so seconds 3, 2, 1 each fire exactly once before GO.
		countdownTargetMs = System.currentTimeMillis() + 3500L;
		cancelSync.setVisible(true);
		syncStart.setEnabled(false);
		startNow.setEnabled(false);
		tick();
	}

	private void onSyncStart()
	{
		if (hunt == null)
		{
			return;
		}
		long now = System.currentTimeMillis();
		// Round up to the next 15-second boundary, ensuring at least 15s of countdown.
		long minMs = now + 15_000L;
		long target = ((minMs / 15_000L) + (minMs % 15_000L == 0 ? 0 : 1)) * 15_000L;
		countdownTargetMs = target;
		cancelSync.setVisible(true);
		syncStart.setEnabled(false);
		startNow.setEnabled(false);
		tick();
	}

	private void cancelCountdownIfRunning()
	{
		if (countdownTargetMs != 0L)
		{
			countdownTargetMs = 0L;
			countdown.setText(" ");
			cancelSync.setVisible(false);
			syncStart.setEnabled(true);
			startNow.setEnabled(true);
			host.getCountdownOverlay().clear();
			lastCountdownDigit = -1;
		}
	}

	private void onReset()
	{
		if (hunt == null)
		{
			return;
		}
		int choice = JOptionPane.showConfirmDialog(this,
			"Reset all progress and the timer for \"" + hunt.getName() + "\"?",
			"Reset hunt", JOptionPane.OK_CANCEL_OPTION, JOptionPane.WARNING_MESSAGE);
		if (choice == JOptionPane.OK_OPTION)
		{
			host.getActive().reset(hunt.getId());
			host.getDetector().resetForNewHunt();
			refresh();
		}
	}

	private void onExport()
	{
		if (hunt == null)
		{
			return;
		}
		String code = host.getHuntManager().exportHunt(hunt);
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(code), null);
		}
		catch (RuntimeException ignored)
		{
			// Headless or restricted clipboard — fall through to the dialog.
		}
		JTextArea area = new JTextArea(code, 8, 40);
		area.setLineWrap(true);
		area.setWrapStyleWord(false);
		area.setEditable(false);
		area.selectAll();
		JScrollPane sp = new JScrollPane(area);
		sp.setPreferredSize(new Dimension(360, 200));
		JOptionPane.showMessageDialog(this, sp,
			"Hunt code (copied to clipboard)", JOptionPane.INFORMATION_MESSAGE);
	}

	private void onDelete()
	{
		if (hunt == null)
		{
			return;
		}
		int choice = JOptionPane.showConfirmDialog(this,
			"Delete \"" + hunt.getName() + "\" and its progress?",
			"Puzzle hunt", JOptionPane.YES_NO_OPTION);
		if (choice != JOptionPane.YES_OPTION)
		{
			return;
		}
		try
		{
			host.getHuntManager().deleteHunt(hunt.getId());
			if (host.getActive().getActiveHunt() != null && hunt.getId().equals(host.getActive().getActiveHunt().getId()))
			{
				host.getActive().stop();
			}
			host.showHome();
		}
		catch (IOException ex)
		{
			log.debug("Failed to delete hunt", ex);
			JOptionPane.showMessageDialog(this, "Could not delete: " + ex.getMessage(),
				"Puzzle hunt", JOptionPane.ERROR_MESSAGE);
		}
	}
}

package com.puzzlehunt;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.puzzlehunt.model.HuntProgress;
import com.puzzlehunt.model.PuzzleHunt;
import com.puzzlehunt.model.PuzzleStep;
import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Loads and saves {@link PuzzleHunt}s and their {@link HuntProgress} from the
 * <code>.runelite/puzzle-hunt</code> directory.
 *
 * <p>Each hunt is stored as a single JSON file named <code>{id}.json</code> in
 * the {@code hunts/} subdirectory; per-hunt progress is stored alongside it in
 * {@code progress/{id}.json}. Splitting the two files keeps progress writes
 * (which happen frequently while playing) cheap and isolated from the hunt
 * definition itself, which players will sometimes want to share verbatim.
 *
 * <p>All filesystem operations live on whatever thread invokes them; callers
 * that are on the client thread should dispatch through an executor.
 */
@Slf4j
@Singleton
public class HuntManager
{
	static final String PLUGIN_DIR_NAME = "puzzle-hunt";
	private static final String HUNTS_DIR_NAME = "hunts";
	private static final String PROGRESS_DIR_NAME = "progress";
	private static final String JSON_EXT = ".json";

	private final Gson gson;
	private final Path pluginDir;
	private final Path huntsDir;
	private final Path progressDir;

	@Inject
	HuntManager(Gson gson)
	{
		this(gson, RuneLite.RUNELITE_DIR.toPath().resolve(PLUGIN_DIR_NAME));
	}

	/** Visible for tests. */
	HuntManager(Gson gson, Path pluginDir)
	{
		this.gson = gson;
		this.pluginDir = pluginDir;
		this.huntsDir = pluginDir.resolve(HUNTS_DIR_NAME);
		this.progressDir = pluginDir.resolve(PROGRESS_DIR_NAME);
	}

	/** Deep-clones a {@link PuzzleStep} via the configured Gson and assigns
	 * a fresh id so progress tracking treats it as a separate step. */
	public PuzzleStep cloneStep(PuzzleStep src)
	{
		if (src == null)
		{
			return null;
		}
		PuzzleStep copy = gson.fromJson(gson.toJson(src), PuzzleStep.class);
		copy.setId(java.util.UUID.randomUUID().toString());
		return copy;
	}

	/** Loads every saved hunt. Corrupt files are skipped with a debug log. */
	public List<PuzzleHunt> loadAllHunts()
	{
		if (!Files.isDirectory(huntsDir))
		{
			return new ArrayList<>();
		}
		List<PuzzleHunt> hunts = new ArrayList<>();
		try (Stream<Path> files = Files.list(huntsDir))
		{
			files
				.filter(p -> p.getFileName().toString().endsWith(JSON_EXT))
				.sorted()
				.forEach(p ->
				{
					try (Reader r = Files.newBufferedReader(p, StandardCharsets.UTF_8))
					{
						PuzzleHunt hunt = gson.fromJson(r, PuzzleHunt.class);
						if (hunt != null && hunt.getId() != null)
						{
							hunts.add(hunt);
						}
					}
					catch (IOException | JsonSyntaxException e)
					{
						log.debug("Skipping unreadable hunt file {}", p, e);
					}
				});
		}
		catch (IOException e)
		{
			log.debug("Failed to list hunts directory", e);
		}
		return hunts;
	}

	/** Persists the given hunt to disk. */
	public void saveHunt(PuzzleHunt hunt) throws IOException
	{
		if (hunt == null || hunt.getId() == null || hunt.getId().isEmpty())
		{
			throw new IllegalArgumentException("Hunt must have a non-empty id");
		}
		Files.createDirectories(huntsDir);
		Path target = huntsDir.resolve(safeFileName(hunt.getId()) + JSON_EXT);
		writeJson(target, hunt);
	}

	/** Removes the hunt and any associated progress. */
	public void deleteHunt(String huntId) throws IOException
	{
		Files.deleteIfExists(huntsDir.resolve(safeFileName(huntId) + JSON_EXT));
		Files.deleteIfExists(progressDir.resolve(safeFileName(huntId) + JSON_EXT));
	}

	private static final String EXAMPLES_RESOURCE_DIR = "/com/puzzlehunt/examples/";
	private static final String EXAMPLES_MANIFEST = EXAMPLES_RESOURCE_DIR + "examples.txt";
	private static final String BOOTSTRAP_MARKER = ".examples-bootstrapped";

	/**
	 * Imports the bundled example hunts the first time the plugin is run on
	 * this machine. The marker file lives in {@link #pluginDir} so deleting
	 * the plugin directory (a "reset") will cause the examples to be
	 * re-installed on next start.
	 *
	 * <p>Safe to call from {@code startUp()}; failures are logged at debug and
	 * never escape — a missing / malformed example must not stop the plugin
	 * from loading.
	 */
	public void bootstrapExampleHuntsIfNeeded()
	{
		try
		{
			Files.createDirectories(pluginDir);
			Path marker = pluginDir.resolve(BOOTSTRAP_MARKER);
			if (Files.exists(marker))
			{
				return;
			}
			List<String> resourceNames = readExamplesManifest();
			for (String name : resourceNames)
			{
				importBundledExample(name);
			}
			Files.write(marker, ("Examples installed at " + java.time.Instant.now() + System.lineSeparator())
				.getBytes(StandardCharsets.UTF_8));
		}
		catch (IOException e)
		{
			log.debug("Failed to bootstrap example hunts", e);
		}
	}

	private List<String> readExamplesManifest()
	{
		List<String> names = new ArrayList<>();
		try (java.io.InputStream in = HuntManager.class.getResourceAsStream(EXAMPLES_MANIFEST))
		{
			if (in == null)
			{
				return names;
			}
			try (BufferedReader r = new BufferedReader(new java.io.InputStreamReader(in, StandardCharsets.UTF_8)))
			{
				String line;
				while ((line = r.readLine()) != null)
				{
					String trimmed = line.trim();
					if (trimmed.isEmpty() || trimmed.startsWith("#"))
					{
						continue;
					}
					names.add(trimmed);
				}
			}
		}
		catch (IOException e)
		{
			log.debug("Failed to read examples manifest", e);
		}
		return names;
	}

	private void importBundledExample(String resourceName)
	{
		String path = EXAMPLES_RESOURCE_DIR + resourceName;
		try (java.io.InputStream in = HuntManager.class.getResourceAsStream(path))
		{
			if (in == null)
			{
				log.debug("Example resource missing: {}", path);
				return;
			}
			byte[] raw = in.readAllBytes();
			String content = new String(raw, StandardCharsets.UTF_8).trim();
			if (content.isEmpty())
			{
				// Placeholder file with no code yet — skip silently.
				return;
			}
			importHunt(content);
		}
		catch (IOException | IllegalArgumentException e)
		{
			log.debug("Failed to import bundled example {}", resourceName, e);
		}
	}

	/**
	 * Imports a hunt that may be either raw JSON or a base64-encoded JSON
	 * string (whitespace-tolerant). Saves it under a fresh id if one isn't
	 * already present.
	 */
	public PuzzleHunt importHunt(String content) throws IOException
	{
		String json = decodeIfBase64(content);
		PuzzleHunt hunt;
		try
		{
			hunt = gson.fromJson(json, PuzzleHunt.class);
		}
		catch (JsonSyntaxException e)
		{
			throw new IOException("Imported file is not valid puzzle hunt JSON", e);
		}
		if (hunt == null)
		{
			throw new IOException("Imported file was empty");
		}
		if (hunt.getId() == null || hunt.getId().isEmpty())
		{
			// Generate a fresh hunt by round-tripping through the no-arg ctor.
			PuzzleHunt fresh = new PuzzleHunt();
			hunt.setId(fresh.getId());
		}
		saveHunt(hunt);
		return hunt;
	}

	/** Serialises a hunt to a base64-encoded JSON string suitable for sharing. */
	public String exportHunt(PuzzleHunt hunt)
	{
		String json = gson.toJson(hunt);
		return java.util.Base64.getEncoder().encodeToString(json.getBytes(StandardCharsets.UTF_8));
	}

	private static String decodeIfBase64(String content)
	{
		if (content == null)
		{
			return "";
		}
		String trimmed = content.trim();
		if (trimmed.startsWith("{"))
		{
			// Already JSON.
			return trimmed;
		}
		// Strip surrounding whitespace and base64-decode.
		String compact = trimmed.replaceAll("\\s+", "");
		try
		{
			byte[] decoded = java.util.Base64.getDecoder().decode(compact);
			return new String(decoded, StandardCharsets.UTF_8);
		}
		catch (IllegalArgumentException e)
		{
			// Fall through: maybe a mangled JSON file.
			return trimmed;
		}
	}

	/** Loads progress for the given hunt id, returning a fresh record if none exists. */
	public HuntProgress loadProgress(String huntId)
	{
		Path target = progressDir.resolve(safeFileName(huntId) + JSON_EXT);
		if (!Files.isRegularFile(target))
		{
			HuntProgress empty = new HuntProgress();
			empty.setHuntId(huntId);
			return empty;
		}
		try (BufferedReader r = Files.newBufferedReader(target, StandardCharsets.UTF_8))
		{
			HuntProgress progress = gson.fromJson(r, HuntProgress.class);
			if (progress == null)
			{
				progress = new HuntProgress();
			}
			progress.setHuntId(huntId);
			if (progress.getStepSplits() == null)
			{
				progress.setStepSplits(new LinkedHashMap<>());
			}
			return progress;
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.debug("Failed to read progress for hunt {}; resetting", huntId, e);
			HuntProgress empty = new HuntProgress();
			empty.setHuntId(huntId);
			return empty;
		}
	}

	public void saveProgress(HuntProgress progress) throws IOException
	{
		if (progress == null || progress.getHuntId() == null || progress.getHuntId().isEmpty())
		{
			throw new IllegalArgumentException("Progress must reference a hunt id");
		}
		Files.createDirectories(progressDir);
		Path target = progressDir.resolve(safeFileName(progress.getHuntId()) + JSON_EXT);
		writeJson(target, progress);
	}

	/** Returns the on-disk hunts directory. Visible for tests / diagnostics. */
	Path getPluginDir()
	{
		return pluginDir;
	}

	/** Convenience: hunts paired with their current progress, in load order. */
	public Map<PuzzleHunt, HuntProgress> loadAllWithProgress()
	{
		List<PuzzleHunt> hunts = loadAllHunts();
		Map<PuzzleHunt, HuntProgress> out = new LinkedHashMap<>();
		for (PuzzleHunt hunt : hunts)
		{
			out.put(hunt, loadProgress(hunt.getId()));
		}
		return Collections.unmodifiableMap(out);
	}

	private void writeJson(Path target, Object value) throws IOException
	{
		try (Writer w = new BufferedWriter(Files.newBufferedWriter(target, StandardCharsets.UTF_8)))
		{
			gson.toJson(value, w);
		}
	}

	/**
	 * Strips characters that are problematic in filenames. Hunt ids are
	 * generated from {@link java.util.UUID#randomUUID()} so this is a defence
	 * in depth measure for hand-edited or imported hunts.
	 */
	private static String safeFileName(String raw)
	{
		StringBuilder sb = new StringBuilder(raw.length());
		for (int i = 0; i < raw.length(); i++)
		{
			char c = raw.charAt(i);
			if (Character.isLetterOrDigit(c) || c == '-' || c == '_')
			{
				sb.append(c);
			}
			else
			{
				sb.append('_');
			}
		}
		return sb.length() == 0 ? "hunt" : sb.toString();
	}
}

package com.puzzlehunt;

import com.puzzlehunt.model.HuntMode;
import com.puzzlehunt.model.HuntProgress;
import com.puzzlehunt.model.PuzzleHunt;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Toolkit;
import java.awt.datatransfer.Clipboard;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.io.IOException;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;

@Slf4j
class HomeView extends JPanel
{
	private final PuzzleHuntPanel host;
	private final JPanel huntList = new JPanel();

	HomeView(PuzzleHuntPanel host)
	{
		this.host = host;
		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(buildHeader(), BorderLayout.NORTH);

		JPanel buttons = new JPanel(new GridLayout(2, 1, 0, 4));
		buttons.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JButton create = PanelComponents.button("Create new hunt");
		create.addActionListener(e -> host.showCreate(null));
		buttons.add(create);
		JButton importBtn = PanelComponents.button("Import from clipboard");
		importBtn.addActionListener(e -> onImport());
		buttons.add(importBtn);

		JPanel center = new JPanel(new BorderLayout(0, 8));
		center.setBackground(ColorScheme.DARK_GRAY_COLOR);
		center.add(buttons, BorderLayout.NORTH);

		huntList.setLayout(new BoxLayout(huntList, BoxLayout.Y_AXIS));
		huntList.setBackground(ColorScheme.DARK_GRAY_COLOR);
		center.add(huntList, BorderLayout.CENTER);

		add(center, BorderLayout.CENTER);
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel title = new JLabel("Puzzle Hunt", SwingConstants.LEFT);
		title.setForeground(Color.WHITE);
		header.add(title, BorderLayout.NORTH);
		JLabel subtitle = new JLabel("Build, run and share custom hunts");
		subtitle.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		header.add(subtitle, BorderLayout.SOUTH);
		return header;
	}

	void refresh()
	{
		huntList.removeAll();
		Map<PuzzleHunt, HuntProgress> all = host.getHuntManager().loadAllWithProgress();
		if (all.isEmpty())
		{
			JLabel empty = new JLabel("No hunts saved yet.");
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setAlignmentX(LEFT_ALIGNMENT);
			huntList.add(Box.createVerticalStrut(8));
			huntList.add(empty);
		}
		else
		{
			huntList.add(Box.createVerticalStrut(8));
			for (Map.Entry<PuzzleHunt, HuntProgress> entry : all.entrySet())
			{
				JPanel row = buildHuntRow(entry.getKey(), entry.getValue());
				huntList.add(row);
				huntList.add(Box.createVerticalStrut(4));
			}
		}
		huntList.revalidate();
		huntList.repaint();
	}

	private JPanel buildHuntRow(PuzzleHunt hunt, HuntProgress progress)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 56));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		JLabel name = new JLabel(hunt.getName());
		name.setForeground(Color.WHITE);
		row.add(name, BorderLayout.NORTH);

		int total = hunt.getSteps() == null ? 0 : hunt.getSteps().size();
		int done = progress.getStepSplits() == null ? 0 : progress.getStepSplits().size();
		String modeLabel = hunt.getMode() == HuntMode.TREASURE_TRAIL ? "Treasure Trail" : "Diary";
		JLabel meta = new JLabel(modeLabel + " — " + done + "/" + total + " steps"
			+ (progress.isCompleted() ? " ✓" : ""));
		meta.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		row.add(meta, BorderLayout.SOUTH);

		row.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseClicked(MouseEvent e) { host.showDetail(hunt); }
		});
		return row;
	}

	private void onImport()
	{
		String code;
		try
		{
			Clipboard cb = Toolkit.getDefaultToolkit().getSystemClipboard();
			if (cb == null || !cb.isDataFlavorAvailable(DataFlavor.stringFlavor))
			{
				JOptionPane.showMessageDialog(this, "Clipboard does not contain text.",
					"Puzzle hunt", JOptionPane.WARNING_MESSAGE);
				return;
			}
			code = (String) cb.getData(DataFlavor.stringFlavor);
		}
		catch (IllegalStateException | UnsupportedFlavorException | IOException ex)
		{
			log.debug("Failed to read clipboard", ex);
			JOptionPane.showMessageDialog(this, "Could not read clipboard: " + ex.getMessage(),
				"Puzzle hunt", JOptionPane.ERROR_MESSAGE);
			return;
		}
		if (code == null || code.trim().isEmpty())
		{
			JOptionPane.showMessageDialog(this, "Clipboard is empty.",
				"Puzzle hunt", JOptionPane.WARNING_MESSAGE);
			return;
		}
		try
		{
			host.getHuntManager().importHunt(code.trim());
			refresh();
		}
		catch (IOException | IllegalArgumentException ex)
		{
			log.debug("Failed to import hunt", ex);
			JOptionPane.showMessageDialog(this, "Could not import hunt: " + ex.getMessage(),
				"Puzzle hunt", JOptionPane.ERROR_MESSAGE);
		}
	}
}
